from pydantic import BaseModelfrom typing import Optional, Any, Dictclass Token(BaseModel):    access_token: str    token_type: strclass TokenData(BaseModel):    username: Optional[str] = Noneclass UserCreate(BaseModel):    username: str    password: str    is_admin: Optional[bool] = False    credits: Optional[int] = 0class UserOut(BaseModel):    id: int    username: str    is_admin: bool    credits: int    class Config:        orm_mode = Trueclass SearchRequest(BaseModel):    type: str    value: strclass SearchResponse(BaseModel):    summary: str    data: Dict[str, Any]    credits_used: int